(function () {
  'use strict';

  const grid = document.getElementById('gallery-grid');
  const lightbox = document.getElementById('lightbox');
  const lightboxImg = document.getElementById('lightbox-image');
  const btnClose = document.getElementById('lightbox-close');
  const btnPrev = document.getElementById('lightbox-prev');
  const btnNext = document.getElementById('lightbox-next');

  let photos = [];
  let currentIndex = 0;
  let lastShownIndex = 0; // used to preload in the direction the user is travelling

  // ---------- Load manifest & build grid (A1, generated by scripts/generate-manifests.mjs) ----------

  fetch('./photos.json')
    .then((res) => res.json())
    .then((data) => {
      photos = data.photos || [];
      renderGrid();
    })
    .catch((err) => console.error('Could not load photos.json', err));

  function renderGrid() {
    grid.innerHTML = '';
    photos.forEach((photo, index) => {
      const img = document.createElement('img');
      img.src = photo.thumb;
      img.loading = 'lazy';
      img.alt = '';
      img.addEventListener('click', () => openLightbox(index));
      grid.appendChild(img);
    });
  }

  // ---------- Lightbox open / close / navigate ----------

  function openLightbox(index) {
    currentIndex = index;
    lastShownIndex = index; // a fresh open always preloads forward first
    showPhoto(index);
    lightbox.classList.add('open');
    lightbox.setAttribute('aria-hidden', 'false');
    document.body.style.overflow = 'hidden';
  }

  function closeLightbox() {
    lightbox.classList.remove('open');
    lightbox.setAttribute('aria-hidden', 'true');
    document.body.style.overflow = '';
    resetZoom();
  }

  // ---------- Photo loading: thumbnail placeholder + neighbor preload (F3.8) ----------
  //
  // Swapping an <img>'s src leaves the OLD bitmap on screen until the new
  // file arrives, so on a slow connection a swipe from A to B briefly shows
  // A again. Two fixes working together:
  //   1. Once the current photo is in, quietly preload the full-res of its
  //      neighbors (and decode them), so a normal swipe is instant.
  //   2. If a photo still isn't ready when it's needed, show its small,
  //      already-cached thumbnail immediately and upgrade to full-res when
  //      it lands, so the wrong photo never appears.

  const PRELOAD_KEEP = 2; // keep decoded full-res images within ±2 of the current photo
  const fullCache = new Map(); // index -> { img, ready, promise }
  let preloadToken = 0; // lets a stale preload chain stop itself after the user moves on

  function decodeImage(img) {
    if (typeof img.decode === 'function') return img.decode();
    return new Promise((resolve, reject) => {
      img.onload = resolve;
      img.onerror = reject;
    });
  }

  // Resolves true once photo `index` is loaded + decoded, false if it failed.
  // Safe to call repeatedly — the same in-flight/finished load is reused.
  function loadFull(index) {
    if (index < 0 || index >= photos.length) return Promise.resolve(false);
    const existing = fullCache.get(index);
    if (existing) return existing.promise;

    const img = new Image();
    img.src = photos[index].full;
    const entry = { img, ready: false, promise: null };
    entry.promise = decodeImage(img)
      .then(() => {
        entry.ready = true;
        return true;
      })
      .catch(() => {
        if (fullCache.get(index) === entry) fullCache.delete(index); // allow a retry later
        return false;
      });
    fullCache.set(index, entry);
    return entry.promise;
  }

  function isFullReady(index) {
    const entry = fullCache.get(index);
    return Boolean(entry && entry.ready);
  }

  // Points an <img> at photo `index`: full-res if already loaded, otherwise
  // the thumbnail, flagged as a placeholder so CSS can size it properly.
  function setPhotoSource(el, index) {
    const ready = isFullReady(index);
    el.src = ready ? photos[index].full : photos[index].thumb;
    el.classList.toggle('is-placeholder', !ready);
  }

  function upgradeToFull(el, index) {
    el.src = photos[index].full;
    el.classList.remove('is-placeholder');
  }

  // Drop decoded images that are far from the current photo so a long
  // browsing session doesn't hold dozens of full-res bitmaps in memory.
  function pruneCache() {
    for (const index of fullCache.keys()) {
      if (Math.abs(index - currentIndex) > PRELOAD_KEEP) fullCache.delete(index);
    }
  }

  function preloadAround(index, goingBack) {
    const token = ++preloadToken;
    const first = goingBack ? index - 1 : index + 1;
    const second = goingBack ? index + 1 : index - 1;

    // Thumbnails are tiny, so grab them right away — they're the fallback
    // if a swipe outruns the full-res preload (grid thumbs are lazy-loaded,
    // so a neighbor's isn't guaranteed to be cached yet).
    [first, second].forEach((i) => {
      if (photos[i]) new Image().src = photos[i].thumb;
    });

    // Full-res: current photo first, then neighbors one at a time in the
    // direction of travel, so they never compete with the photo on screen.
    loadFull(index)
      .then(() => (token === preloadToken ? loadFull(first) : null))
      .then(() => (token === preloadToken ? loadFull(second) : null));
  }

  function showPhoto(index) {
    const goingBack = index < lastShownIndex;
    lastShownIndex = index;

    setPhotoSource(lightboxImg, index);
    // Zoom always resets when moving to a different photo, so nobody
    // lands on the next image already zoomed in from the last one.
    resetZoom();

    // If we're showing the thumbnail placeholder, swap in full-res when it
    // arrives — but only if the user is still on this photo.
    loadFull(index).then((ok) => {
      if (ok && currentIndex === index && lightboxImg.classList.contains('is-placeholder')) {
        upgradeToFull(lightboxImg, index);
        if (scale > MIN_SCALE) {
          clampOrigin();
          applyTransform();
        }
      }
    });

    pruneCache();
    preloadAround(index, goingBack);
  }

  function nextPhoto() {
    if (currentIndex < photos.length - 1) {
      currentIndex += 1;
      showPhoto(currentIndex);
    }
  }

  function prevPhoto() {
    if (currentIndex > 0) {
      currentIndex -= 1;
      showPhoto(currentIndex);
    }
  }

  btnClose.addEventListener('click', closeLightbox);
  btnNext.addEventListener('click', nextPhoto);
  btnPrev.addEventListener('click', prevPhoto);

  lightbox.addEventListener('click', (e) => {
    // .lightbox-stage fills the whole lightbox, so a click on the empty
    // space around the photo lands on the stage, not on .lightbox itself —
    // check both so "click outside the image" actually closes it, while
    // clicks on the photo, the arrows, or the close button (separate
    // elements) don't.
    if (e.target === lightbox || e.target === lightboxImg.parentElement) {
      closeLightbox();
    }
  });

  // ---------- Keyboard navigation (F3.3) ----------

  document.addEventListener('keydown', (e) => {
    if (!lightbox.classList.contains('open')) return;
    if (e.key === 'Escape') closeLightbox();
    if (e.key === 'ArrowRight') nextPhoto();
    if (e.key === 'ArrowLeft') prevPhoto();
  });

  // ---------- Desktop arrows: fade in on mouse movement, fade out when idle (D6) ----------

  let idleTimer = null;
  lightbox.addEventListener('mousemove', () => {
    lightbox.classList.add('arrows-visible');
    clearTimeout(idleTimer);
    idleTimer = setTimeout(() => {
      lightbox.classList.remove('arrows-visible');
    }, 1800);
  });

  // ---------- Custom pinch/double-tap zoom + pan + zoom-aware swipe (F3.6 / F3.7) ----------
  //
  // Rule: at 1x zoom, a horizontal drag/swipe navigates to the next or
  // previous photo, with a Google Photos–style sliding transition that
  // follows the finger and either completes or snaps back on release.
  // Once zoomed in (pinch or double-tap), a drag pans the image instead,
  // and the user has to zoom back out before swipe navigation resumes.

  const MIN_SCALE = 1;
  const MAX_SCALE = 6;
  const DOUBLE_TAP_MS = 280;
  const SWIPE_THRESHOLD_PX = 50;
  const SLIDE_TRANSITION_MS = 220;
  const SLIDE_GAP_PX = 12; // visual space kept between the two photos while sliding

  let scale = MIN_SCALE;
  let originX = 0;
  let originY = 0;

  const activePointers = new Map();
  let pinchStartDistance = 0;
  let pinchStartScale = 1;
  let dragOrigin = null;
  let gestureStart = { x: 0, y: 0 };
  let isPanningGesture = false;
  let lastTapTime = 0;

  // Swipe-slide state — only engaged at 1x zoom (F3.7 rule)
  let isSwipeDragging = false;
  let dragDX = 0;
  let swipeDirection = null; // 'next' | 'prev' | null

  // The "peek" image is the incoming photo that slides in from the edge
  // as the current one slides out, following the finger in real time.
  const stage = lightboxImg.parentElement;
  if (getComputedStyle(stage).position === 'static') {
    stage.style.position = 'relative';
  }
  stage.style.overflow = 'hidden';

  const lightboxImgPeek = document.createElement('img');
  // Same class as the real image so it inherits your actual sizing rule
  // (max-width/max-height/object-fit, however #lightbox-image defines it)
  // instead of us guessing dimensions and distorting differently-shaped photos.
  lightboxImgPeek.className = lightboxImg.className;
  lightboxImgPeek.alt = '';
  lightboxImgPeek.style.position = 'absolute';
  lightboxImgPeek.style.top = '0';
  lightboxImgPeek.style.right = '0';
  lightboxImgPeek.style.bottom = '0';
  lightboxImgPeek.style.left = '0';
  lightboxImgPeek.style.margin = 'auto'; // centers within the stage, same as the real image
  lightboxImgPeek.style.pointerEvents = 'none';
  lightboxImgPeek.style.display = 'none';
  stage.appendChild(lightboxImgPeek);

  function resetZoom() {
    scale = MIN_SCALE;
    originX = 0;
    originY = 0;
    applyTransform();
  }

  function applyTransform() {
    lightboxImg.style.transform = `translate(${originX + dragDX}px, ${originY}px) scale(${scale})`;
  }

  function clampOrigin() {
    const stageRect = stage.getBoundingClientRect();
    const imgRect = lightboxImg.getBoundingClientRect();
    const maxX = Math.max(0, (imgRect.width * scale - stageRect.width) / 2);
    const maxY = Math.max(0, (imgRect.height * scale - stageRect.height) / 2);
    originX = Math.min(maxX, Math.max(-maxX, originX));
    originY = Math.min(maxY, Math.max(-maxY, originY));
  }

  function distanceBetween(p1, p2) {
    return Math.hypot(p1.x - p2.x, p1.y - p2.y);
  }

  function stageWidth() {
    return stage.getBoundingClientRect().width;
  }

  // Positions and shows/hides the peek image as the drag progresses.
  function updateSwipePeek(dx) {
    const width = stageWidth();

    if (dx < 0 && currentIndex < photos.length - 1) {
      swipeDirection = 'next';
    } else if (dx > 0 && currentIndex > 0) {
      swipeDirection = 'prev';
    } else {
      // At a boundary (first/last photo) — nothing to slide in, so the
      // main image still follows the finger but rubber-bands back on release.
      swipeDirection = null;
    }

    if (!swipeDirection) {
      lightboxImgPeek.style.display = 'none';
      return;
    }

    const peekIndex = swipeDirection === 'next' ? currentIndex + 1 : currentIndex - 1;
    if (lightboxImgPeek.dataset.index !== String(peekIndex)) {
      // Full-res if the preload already finished, otherwise the thumbnail
      // (so the incoming photo is visible while it slides in), upgraded
      // when full-res lands — unless the peek has since moved on.
      setPhotoSource(lightboxImgPeek, peekIndex);
      lightboxImgPeek.dataset.index = String(peekIndex);
      loadFull(peekIndex).then((ok) => {
        if (
          ok &&
          lightboxImgPeek.dataset.index === String(peekIndex) &&
          lightboxImgPeek.classList.contains('is-placeholder')
        ) {
          upgradeToFull(lightboxImgPeek, peekIndex);
        }
      });
    }

    const startX = swipeDirection === 'next' ? width + SLIDE_GAP_PX : -(width + SLIDE_GAP_PX);
    lightboxImgPeek.style.transform = `translateX(${startX + dx}px)`;
    lightboxImgPeek.style.display = 'block';
  }

  // Animates the drag to completion (photo change) or back to center
  // (cancel/rubber-band), then cleans up.
  function endSwipeDrag(commit) {
    const width = stageWidth();
    const direction = swipeDirection;

    lightboxImg.style.transition = `transform ${SLIDE_TRANSITION_MS}ms ease-out`;
    lightboxImgPeek.style.transition = `transform ${SLIDE_TRANSITION_MS}ms ease-out`;

    if (commit && direction) {
      dragDX = direction === 'next' ? -(width + SLIDE_GAP_PX) : width + SLIDE_GAP_PX;
      lightboxImgPeek.style.transform = 'translateX(0px)';
    } else {
      dragDX = 0;
      const startX = direction === 'next' ? width + SLIDE_GAP_PX : -(width + SLIDE_GAP_PX);
      lightboxImgPeek.style.transform = `translateX(${startX}px)`;
    }
    applyTransform();

    setTimeout(() => {
      lightboxImgPeek.style.transition = '';
      lightboxImgPeek.classList.remove('panning');
      lightboxImgPeek.style.display = 'none';
      lightboxImgPeek.removeAttribute('data-index');
      dragDX = 0;

      // Clearing lightboxImg's inline transition here would let the CSS
      // default (.lightbox-stage img { transition: transform 0.15s }) take
      // over and animate this reset too — sliding the new photo in a
      // second time from wherever the commit animation left off. Force it
      // off for this one instant snap, then restore it afterward so zoom/
      // pan still transition normally.
      lightboxImg.style.transition = 'none';

      if (commit && direction === 'next') {
        currentIndex += 1;
        showPhoto(currentIndex); // resets zoom/transform for the new photo
      } else if (commit && direction === 'prev') {
        currentIndex -= 1;
        showPhoto(currentIndex);
      } else {
        applyTransform();
      }

      // Force the browser to apply the instant snap before we hand the
      // transition back, so it doesn't get picked up retroactively.
      void lightboxImg.offsetHeight;
      lightboxImg.style.transition = '';

      isSwipeDragging = false;
      swipeDirection = null;
    }, SLIDE_TRANSITION_MS);
  }

  lightboxImg.addEventListener('pointerdown', (e) => {
    lightboxImg.setPointerCapture(e.pointerId);
    activePointers.set(e.pointerId, { x: e.clientX, y: e.clientY });

    if (activePointers.size === 1) {
      gestureStart = { x: e.clientX, y: e.clientY };
      dragOrigin = { x: e.clientX - originX, y: e.clientY - originY };
      // Only treat a single-pointer drag as panning if we're already
      // zoomed in; otherwise it's a candidate swipe-to-navigate.
      isPanningGesture = scale > MIN_SCALE;
      isSwipeDragging = false;
    }

    if (activePointers.size === 2) {
      const [p1, p2] = [...activePointers.values()];
      pinchStartDistance = distanceBetween(p1, p2);
      pinchStartScale = scale;
      isPanningGesture = false;
    }
  });

  lightboxImg.addEventListener('pointermove', (e) => {
    if (!activePointers.has(e.pointerId)) return;
    activePointers.set(e.pointerId, { x: e.clientX, y: e.clientY });

    if (activePointers.size === 2) {
      const [p1, p2] = [...activePointers.values()];
      const ratio = distanceBetween(p1, p2) / pinchStartDistance;
      scale = Math.min(MAX_SCALE, Math.max(MIN_SCALE, pinchStartScale * ratio));
      lightboxImg.classList.add('panning');
      clampOrigin();
      applyTransform();
      return;
    }

    if (activePointers.size === 1 && isPanningGesture) {
      lightboxImg.classList.add('panning');
      originX = e.clientX - dragOrigin.x;
      originY = e.clientY - dragOrigin.y;
      clampOrigin();
      applyTransform();
      return;
    }

    if (activePointers.size === 1 && !isPanningGesture && scale === MIN_SCALE) {
      const dx = e.clientX - gestureStart.x;
      const dy = e.clientY - gestureStart.y;
      // Only commit to a slide-drag once movement is clearly horizontal,
      // so a vertical scroll/dismiss gesture isn't hijacked.
      if (!isSwipeDragging && Math.abs(dx) < 10) return;
      if (!isSwipeDragging && Math.abs(dy) > Math.abs(dx)) return;

      if (!isSwipeDragging) {
        // .lightbox-stage img has a default transform transition (used for
        // the release ease); kill it during the live drag, same as .panning
        // already does for pinch/pan, so the image tracks the finger 1:1.
        lightboxImg.classList.add('panning');
        lightboxImgPeek.classList.add('panning');
      }
      isSwipeDragging = true;
      dragDX = dx;
      applyTransform();
      updateSwipePeek(dx);
    }
  });

  function handlePointerEnd(e) {
    const wasSwipeDrag = isSwipeDragging;
    const dx = e.clientX - gestureStart.x;
    const dy = e.clientY - gestureStart.y;

    activePointers.delete(e.pointerId);
    lightboxImg.classList.remove('panning');

    if (wasSwipeDrag && activePointers.size === 0) {
      const shouldCommit =
        swipeDirection && Math.abs(dx) > SWIPE_THRESHOLD_PX && Math.abs(dx) > Math.abs(dy);
      endSwipeDrag(shouldCommit);
    }

    if (activePointers.size === 0) {
      isPanningGesture = false;
      if (!wasSwipeDrag && scale < MIN_SCALE) resetZoom();

      // Double-tap / double-click to toggle zoom.
      const now = Date.now();
      if (!wasSwipeDrag && now - lastTapTime < DOUBLE_TAP_MS) {
        if (scale > MIN_SCALE) {
          resetZoom();
        } else {
          scale = 2;
          applyTransform();
        }
      }
      lastTapTime = now;
    }
  }

  lightboxImg.addEventListener('pointerup', handlePointerEnd);
  lightboxImg.addEventListener('pointercancel', handlePointerEnd);
})();